use super::super::path::Point;
use super::misc::basis_point;
use super::misc::cardinal_point;
use super::misc::catmull_rom_point;
use super::misc::natural_spline_derivs;

/// Interpolate using step function.
pub(super) fn interpolate_step(points: &[Point], position: f64) -> Vec<Point> {
    let mut result = Vec::with_capacity(points.len() * 2);

    for i in 0..points.len() {
        result.push(points[i]);

        if i < points.len() - 1 {
            let mid_x = points[i].x + (points[i + 1].x - points[i].x) * position;
            result.push(Point::new(mid_x, points[i].y));
            result.push(Point::new(mid_x, points[i + 1].y));
        }
    }

    result
}

/// Interpolate using basis spline.
pub(super) fn interpolate_basis(points: &[Point]) -> Vec<Point> {
    if points.len() < 2 {
        return points.to_vec();
    }

    let n = points.len();
    let subdivisions = 16;
    let mut result = Vec::with_capacity((n - 1) * subdivisions + 1);

    // Add reflected points for endpoints
    let p0 = Point::new(
        2.0 * points[0].x - points[1].x,
        2.0 * points[0].y - points[1].y,
    );
    let pn = Point::new(
        2.0 * points[n - 1].x - points[n - 2].x,
        2.0 * points[n - 1].y - points[n - 2].y,
    );

    for i in 0..n - 1 {
        let v0 = if i == 0 { p0 } else { points[i - 1] };
        let v1 = points[i];
        let v2 = points[i + 1];
        let v3 = if i == n - 2 { pn } else { points[i + 2] };

        for j in 0..subdivisions {
            let t = j as f64 / subdivisions as f64;
            result.push(basis_point(&v0, &v1, &v2, &v3, t));
        }
    }

    // Add final point
    result.push(*points.last().unwrap());

    result
}

/// Interpolate using bundle curve.
pub(super) fn interpolate_bundle(points: &[Point], beta: f64) -> Vec<Point> {
    // Bundle is a blend between straight line and basis curve
    let basis_points = interpolate_basis(points);

    if (beta - 1.0).abs() < 0.001 {
        return basis_points;
    }

    if beta.abs() < 0.001 {
        // Straight line from first to last
        return vec![points[0], *points.last().unwrap()];
    }

    // Blend between straight line and basis
    let first = points[0];
    let last = *points.last().unwrap();

    basis_points
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let t = i as f64 / (basis_points.len() - 1) as f64;
            let straight = Point::new(
                first.x + (last.x - first.x) * t,
                first.y + (last.y - first.y) * t,
            );
            Point::new(
                straight.x + (p.x - straight.x) * beta,
                straight.y + (p.y - straight.y) * beta,
            )
        })
        .collect()
}

/// Interpolate using cardinal spline.
pub(super) fn interpolate_cardinal(points: &[Point], tension: f64) -> Vec<Point> {
    if points.len() < 2 {
        return points.to_vec();
    }

    let n = points.len();
    let subdivisions = 16;
    let k = (1.0 - tension) / 2.0;
    let mut result = Vec::with_capacity((n - 1) * subdivisions + 1);

    result.push(points[0]);

    for i in 0..n - 1 {
        let p0 = if i > 0 { points[i - 1] } else { points[i] };
        let p1 = points[i];
        let p2 = points[i + 1];
        let p3 = if i + 2 < n {
            points[i + 2]
        } else {
            points[i + 1]
        };

        for j in 1..=subdivisions {
            let t = j as f64 / subdivisions as f64;
            result.push(cardinal_point(&p0, &p1, &p2, &p3, t, k));
        }
    }

    result
}

/// Interpolate using Catmull-Rom spline.
pub(super) fn interpolate_catmull_rom(points: &[Point], alpha: f64) -> Vec<Point> {
    if points.len() < 2 {
        return points.to_vec();
    }

    let n = points.len();
    let subdivisions = 16;
    let mut result = Vec::with_capacity((n - 1) * subdivisions + 1);

    result.push(points[0]);

    for i in 0..n - 1 {
        let p0 = if i > 0 { points[i - 1] } else { points[i] };
        let p1 = points[i];
        let p2 = points[i + 1];
        let p3 = if i + 2 < n {
            points[i + 2]
        } else {
            points[i + 1]
        };

        for j in 1..=subdivisions {
            let t = j as f64 / subdivisions as f64;
            result.push(catmull_rom_point(&p0, &p1, &p2, &p3, t, alpha));
        }
    }

    result
}

/// Interpolate using monotone X spline.
pub(super) fn interpolate_monotone_x(points: &[Point]) -> Vec<Point> {
    if points.len() < 2 {
        return points.to_vec();
    }

    let n = points.len();
    let subdivisions = 16;

    // Calculate slopes
    let mut slopes: Vec<f64> = Vec::with_capacity(n);

    for i in 0..n {
        if i == 0 {
            slopes.push((points[1].y - points[0].y) / (points[1].x - points[0].x).max(1e-8));
        } else if i == n - 1 {
            slopes.push(
                (points[n - 1].y - points[n - 2].y) / (points[n - 1].x - points[n - 2].x).max(1e-8),
            );
        } else {
            let s0 = (points[i].y - points[i - 1].y) / (points[i].x - points[i - 1].x).max(1e-8);
            let s1 = (points[i + 1].y - points[i].y) / (points[i + 1].x - points[i].x).max(1e-8);

            // Preserve monotonicity
            if s0 * s1 <= 0.0 {
                slopes.push(0.0);
            } else {
                slopes.push(3.0 * (s0 + s1) / ((s0 / s1 + 2.0) + (s1 / s0 + 2.0)));
            }
        }
    }

    let mut result = Vec::with_capacity((n - 1) * subdivisions + 1);
    result.push(points[0]);

    for i in 0..n - 1 {
        let dx = points[i + 1].x - points[i].x;

        for j in 1..=subdivisions {
            let t = j as f64 / subdivisions as f64;
            let t2 = t * t;
            let t3 = t2 * t;

            let h00 = 2.0 * t3 - 3.0 * t2 + 1.0;
            let h10 = t3 - 2.0 * t2 + t;
            let h01 = -2.0 * t3 + 3.0 * t2;
            let h11 = t3 - t2;

            result.push(Point::new(
                points[i].x + dx * t,
                h00 * points[i].y
                    + h10 * dx * slopes[i]
                    + h01 * points[i + 1].y
                    + h11 * dx * slopes[i + 1],
            ));
        }
    }

    result
}

/// Interpolate using monotone Y spline.
pub(super) fn interpolate_monotone_y(points: &[Point]) -> Vec<Point> {
    // Swap x and y, interpolate, then swap back
    let swapped: Vec<Point> = points.iter().map(|p| Point::new(p.y, p.x)).collect();
    let result = interpolate_monotone_x(&swapped);
    result.iter().map(|p| Point::new(p.y, p.x)).collect()
}

/// Interpolate using natural cubic spline.
pub(super) fn interpolate_natural(points: &[Point]) -> Vec<Point> {
    if points.len() < 2 {
        return points.to_vec();
    }

    let n = points.len();
    let subdivisions = 16;

    // Solve tridiagonal system for second derivatives
    let second_derivs_x = natural_spline_derivs(|i| points[i].x, points.len());
    let second_derivs_y = natural_spline_derivs(|i| points[i].y, points.len());

    let mut result = Vec::with_capacity((n - 1) * subdivisions + 1);
    result.push(points[0]);

    for i in 0..n - 1 {
        let h = 1.0; // Assuming uniform parameterization

        for j in 1..=subdivisions {
            let t = j as f64 / subdivisions as f64;

            let a = 1.0 - t;
            let b = t;

            let x = a * points[i].x
                + b * points[i + 1].x
                + (a * a * a - a) * second_derivs_x[i] * h * h / 6.0
                + (b * b * b - b) * second_derivs_x[i + 1] * h * h / 6.0;

            let y = a * points[i].y
                + b * points[i + 1].y
                + (a * a * a - a) * second_derivs_y[i] * h * h / 6.0
                + (b * b * b - b) * second_derivs_y[i + 1] * h * h / 6.0;

            result.push(Point::new(x, y));
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::shape::path::Point;

    #[test]
    fn test_interpolate_natural_preserves_endpoints() {
        let points = vec![
            Point::new(0.0, 0.0),
            Point::new(1.0, 2.0),
            Point::new(2.0, 1.0),
            Point::new(3.0, 3.0),
        ];
        let result = interpolate_natural(&points);
        assert!(!result.is_empty());
        assert!((result[0].x - points[0].x).abs() < 1e-10);
        assert!((result[0].y - points[0].y).abs() < 1e-10);
        let last = result.last().unwrap();
        assert!((last.x - points.last().unwrap().x).abs() < 1e-10);
        assert!((last.y - points.last().unwrap().y).abs() < 1e-10);
    }

    #[test]
    fn test_interpolate_natural_short_input() {
        let points = vec![Point::new(0.0, 0.0), Point::new(1.0, 1.0)];
        let result = interpolate_natural(&points);
        // With two points the spline degenerates to a straight line but still
        // emits the standard number of subdivisions.
        assert_eq!(result.len(), 17);
        assert!((result[0].x - points[0].x).abs() < 1e-10);
        assert!((result.last().unwrap().x - points[1].x).abs() < 1e-10);
    }
}
